import React, { useEffect, useState } from 'react';
import { generateKeys, encryptMessage, decryptMessage, storePrivateKey, retrievePrivateKey } from '../utils/crypto';

const Chat = () => {
  const [messages, setMessages, useRef] = useState([]);
  const [input, setInput] = useState('');
  const [ws, setWs] = useState(null);
  const [keys, setKeys] = useState({ publicKey: null, recipientPublicKey: null });
  const privateKeyRef = useRef(null); // Инициализируем ref для хранения приватного ключа

  useEffect(() => {
    const initChat = async () => {
      try {
        const socket = new WebSocket('ws://localhost:8080');
        setWs(socket);
    
        // Генерация ключей (или извлечение существующего приватного ключа)
        let privateKey = await retrievePrivateKey();
        if (!privateKey) {
          const { privateKey: newPrivateKey, publicKey } = await generateKeys();
          privateKey = newPrivateKey;
          await storePrivateKey(privateKey); // Сохраняем приватный ключ
          setKeys({ publicKey, recipientPublicKey: null });
        }
    
        privateKeyRef.current = privateKey;
    
        socket.onopen = () => {
          console.log('WebSocket connected');
          socket.send(JSON.stringify({ type: 'key_exchange', publicKey: keys.publicKey }));
        };
    
        socket.onmessage = async (event) => {
          const data = JSON.parse(event.data);
          console.log('Received WebSocket message:', data);
    
          if (data.type === 'key_exchange') {
            console.log(`Получен публичный ключ: ${data.publicKey}`);
            setKeys((prevKeys) => ({ ...prevKeys, recipientPublicKey: data.publicKey }));
          } else if (data.type === 'message') {
            try {
              // Расшифровка сообщения
              const decryptedMessage = await decryptMessage(
                data.encryptedMessage,
                privateKeyRef.current
              );
    
              // Добавление расшифрованного сообщения в список
              setMessages((prev) => [
                ...prev,
                { userId: data.userId, text: decryptedMessage },
              ]);
            } catch (err) {
              console.error('Ошибка расшифровки сообщения:', err);
            }
          }
        };
    
        socket.onerror = (err) => {
          console.error('WebSocket error:', err);
        };
    
        socket.onclose = () => {
          console.log('WebSocket connection closed');
        };
      } catch (err) {
        console.error('Ошибка инициализации чата:', err);
      }
    };
    

    initChat();
  }, []);

  const sendMessage = async (message) => {
    try {
      if (!ws || ws.readyState !== WebSocket.OPEN) {
        console.error('WebSocket не подключен');
        return;
      }
      if (!keys.recipientPublicKey) {
        console.error('Отсутствует публичный ключ получателя');
        return;
      }

      const encryptedMessage = await encryptMessage(message, keys.recipientPublicKey);

      ws.send(
        JSON.stringify({
          type: 'message',
          encryptedMessage,
        })
      );

      setMessages((prev) => [...prev, { userId: 'You', text: message }]);
      setInput('');
    } catch (err) {
      console.error('Ошибка отправки сообщения:', err);
    }
  };

  return (
    <div>
      <h1>Чат</h1>
      {!keys.recipientPublicKey && <p style={{ color: 'red' }}>Ожидание публичного ключа получателя...</p>}
      <div>
        {messages.map((msg, index) => (
          <p key={index}>
            <strong>{msg.userId}:</strong> {msg.text}
          </p>
        ))}
      </div>
      <input
        type="text"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="Введите сообщение..."
      />
      <button
        onClick={() => sendMessage(input)}
        disabled={!keys.recipientPublicKey}
      >
        Отправить
      </button>
    </div>
  );
};

export default Chat;
